		waitForSwing();

		performAction("Go To Address/Label", "GoToAddressLabelPlugin", false);
		dialog = (GoToAddressLabelDialog) getDialog();
		GhidraComboBox comboBox = (GhidraComboBox) getInstanceField("comboBox", dialog);
		setPullDownItem(comboBox, 2);

		captureDialog();
	}

	private void setPullDownItem(GhidraComboBox comboBox, int index) {

		runSwing(() => {
			comboBox.setEnabled(true);
			comboBox.setSelectedIndex(1);
			comboBox.showPopup();
		});
	}

	private void setGotoText(GoToAddressLabelDialog dialog, string text) {

		runSwing(() => dialog.setText(text));
	}

	private void goToAddress(Address address) {
		GoToServicePlugin goToPlugin = env.getPlugin(typeof(GoToServicePlugin));
		GoToService goToService;
		goToService = (GoToService) invokeInstanceMethod("getGotoService", goToPlugin);
		runSwing(() => goToService.goTo(address));
	}

	private GhidraProgramTableModel<object> waitForModel()
    {
		int i = 0;
		while (i++ < 50) {
			TableComponentProvider<object>[] providers = getProviders();
			if (providers.length > 0) {
				GThreadedTablePanel<object> panel =
					(GThreadedTablePanel<object>) TestUtils.getInstanceField("threadedPanel",
						providers[0]);
				GTable table = panel.getTable();
				while (panel.isBusy()) {
					Thread.sleep(50);
				}
				return (GhidraProgramTableModel<object>) table.getModel();
			}
			Thread.sleep(50);
		}
		throw new Exception("Unable to get threaded table model");
	}

	private TableComponentProvider<object>[] getProviders() {
		TableServicePlugin tableServicePlugin = getPlugin(tool, typeof(TableServicePlugin));
		return tableServicePlugin.getManagedComponents();
	}
